

  CREATE TABLE "CO"."STORES"
   (	"STORE_ID" NUMBER(*,0) GENERATED BY DEFAULT ON NULL AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 24 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE,
	"STORE_NAME" VARCHAR2(255 CHAR) NOT NULL ENABLE,
	"WEB_ADDRESS" VARCHAR2(100 CHAR),
	"PHYSICAL_ADDRESS" VARCHAR2(512 CHAR),
	"LATITUDE" NUMBER(9,6),
	"LONGITUDE" NUMBER(9,6),
	"LOGO" BLOB,
	"LOGO_MIME_TYPE" VARCHAR2(512 CHAR),
	"LOGO_FILENAME" VARCHAR2(512 CHAR),
	"LOGO_CHARSET" VARCHAR2(512 CHAR),
	"LOGO_LAST_UPDATED" DATE
   ) SEGMENT CREATION IMMEDIATE
  PCTFREE 10 PCTUSED 40 INITRANS 1 MAXTRANS 255
 NOCOMPRESS LOGGING
  STORAGE(INITIAL 65536 NEXT 1048576 MINEXTENTS 1 MAXEXTENTS 2147483645
  PCTINCREASE 0 FREELISTS 1 FREELIST GROUPS 1
  BUFFER_POOL DEFAULT FLASH_CACHE DEFAULT CELL_FLASH_CACHE DEFAULT)
  TABLESPACE "USERS"
 LOB ("LOGO") STORE AS SECUREFILE (
  TABLESPACE "USERS" ENABLE STORAGE IN ROW 4000 CHUNK 8192
  NOCACHE LOGGING  NOCOMPRESS  KEEP_DUPLICATES
  STORAGE(INITIAL 262144 NEXT 1048576 MINEXTENTS 1 MAXEXTENTS 2147483645
  PCTINCREASE 0
  BUFFER_POOL DEFAULT FLASH_CACHE DEFAULT CELL_FLASH_CACHE DEFAULT)) ;
ALTER TABLE "CO"."STORES" ADD CONSTRAINT "STORES_PK" PRIMARY KEY ("STORE_ID")
  USING INDEX PCTFREE 10 INITRANS 2 MAXTRANS 255
  STORAGE(INITIAL 65536 NEXT 1048576 MINEXTENTS 1 MAXEXTENTS 2147483645
  PCTINCREASE 0 FREELISTS 1 FREELIST GROUPS 1
  BUFFER_POOL DEFAULT FLASH_CACHE DEFAULT CELL_FLASH_CACHE DEFAULT)
  TABLESPACE "USERS"  ENABLE;
ALTER TABLE "CO"."STORES" ADD CONSTRAINT "STORE_NAME_U" UNIQUE ("STORE_NAME")
  USING INDEX PCTFREE 10 INITRANS 2 MAXTRANS 255
  STORAGE(INITIAL 65536 NEXT 1048576 MINEXTENTS 1 MAXEXTENTS 2147483645
  PCTINCREASE 0 FREELISTS 1 FREELIST GROUPS 1
  BUFFER_POOL DEFAULT FLASH_CACHE DEFAULT CELL_FLASH_CACHE DEFAULT)
  TABLESPACE "USERS"  ENABLE;
ALTER TABLE "CO"."STORES" ADD CONSTRAINT "STORE_AT_LEAST_ONE_ADDRESS_C" CHECK (
    web_address IS NOT NULL or physical_address IS NOT NULL
  ) ENABLE;
  INSERT /*+  APPEND  NESTED_TABLE_SET_REFS  */ INTO
  "CO"."STORES"  KUT$ ("STORE_ID", "STORE_NAME", "WEB_ADDRESS", "PHYSICAL_ADDRESS", "LATITUDE", "LONGITUDE", "LOGO", "LOGO_MIME_TYPE", "LOGO_FILENAME", "LOGO_CHARSET", "LOGO_LAST_UPDATED")
  SELECT /*+ NESTED_TABLE_GET_REFS  */
  "STORE_ID", "STORE_NAME", "WEB_ADDRESS", "PHYSICAL_ADDRESS", "LATITUDE", "LONGITUDE", "LOGO", "LOGO_MIME_TYPE", "LOGO_FILENAME", "LOGO_CHARSET", "LOGO_LAST_UPDATED" FROM "CO"."STORES"@ KU$;

